import json,html
from pathlib import Path
ROOT=Path(__file__).parent.parent/'output';out=ROOT/'registry-label-verification'
reports=[json.loads((ROOT/name/'results.json').read_text()) for name in ['registry-label-verification','registry-label-approver1','registry-label-approver2']]
assert all(r['status']=='passed' for r in reports)
examples=[('household_housing_services_tab','Housing and basic services'),('Household Membershib','Household membership'),('individual_livelihood_tab','Livelihood and employment'),('Register Ingest Process Status','Registry publication status'),('NOT_APPLICABLE','Not applicable'),('table.noData','No records available'),('Error occured while saving form','An error occurred while saving the form')]
rows=''.join('<tr><td>'+html.escape(a)+'</td><td>'+html.escape(b)+'</td></tr>' for a,b in examples)
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registry readable labels</title><style>body{{font:16px/1.6 system-ui;background:#f1f5f0;color:#173e34;margin:0}}main{{max-width:950px;margin:24px auto;padding:28px;background:white;border:1px solid #d2dfd3;border-radius:16px}}h1,a{{color:#155e50}}table{{border-collapse:collapse;width:100%}}td,th{{padding:12px;text-align:left;border-bottom:1px solid #d2dfd3;overflow-wrap:anywhere}}img{{max-width:390px;width:100%;border-radius:12px}}</style><main><h1>Readable registry labels: verified</h1><p>13 November 2026 · Updated the native English locale, shared field display formatting and the registry presentation layer. Business records, identifiers and persisted workflow codes were not modified.</p><table><tr><th>Previous label</th><th>Readable label</th></tr>{rows}</table><p>Passed {sum(len(r['checks']) for r in reports)} desktop/mobile checks across the household and individual master lists, all nine record tabs, registration-review pages, change requests, and both approver accounts’ task queues. The checks found no remaining underscore label keys, the audited spelling mistakes, page overflow or JavaScript errors. The individual-registration and approver queues currently have no pending test records.</p><p>Table empty-state and dialog messages were also reviewed. Secondary-tab tables now scroll inside their own containers on mobile.</p><p><a href="results.json">Officer and record-tab checks</a> · <a href="../registry-label-approver1/results.json">First approver</a> · <a href="../registry-label-approver2/results.json">Second approver</a></p><img src="_register_household_tab-2-390.png" alt="Readable household tabs and housing fields on mobile"></main></html>'''
(out/'verification.html').write_text(page,encoding='utf-8');print('Built readable-label verification report')
